const common = ['source_id', 'json_pointer', 'row_key', 'parent_key', 'ordinal', 'member_key', 'person_ref', 'state_ref'];
export const ATLAS_TABLE_COLUMNS = Object.freeze(Object.fromEntries(definitions.map((d) => [d.table, Object.freeze([...common, ...d.nodes.flatMap((n) => [n.name + '__type', ...(n.types.some((t) => !['object', 'array', 'map', 'null'].includes(t)) ? [n.name] : [])])])])));
const escape = (s) => String(s).replace(/~/g, '~0').replace(/\//g, '~1');
const kind = (v) => v === undefined ? null : v === null ? 'null' : Array.isArray(v) ? 'array' : typeof v;
const get = (v, path) => path.reduce((x, p) => x?.[p], v);
const fail = (message) => { throw Object.assign(new Error('E_ATLAS_SHAPE: ' + message), { code: 'E_ATLAS_SHAPE' }); };

export function mapAtlasData({ files, bundle }) {
  if (!Array.isArray(files)) fail('files must be an array');
  const tables = Object.fromEntries(definitions.map((d) => [d.table, []]));
  const persons = new Set((bundle?.files?.find((f) => f.logical_path === 'lore/name-pools/person-id-registry.json')?.document?.persons ?? []).map((p) => p.id));
  const states = new Set((bundle?.files?.find((f) => f.logical_path === 'lore/name-pools/values-cast.json')?.document?.people ?? []).map((p) => p.state));
  const children = (d) => definitions.filter((x) => x.parent === d.table);
  const seen = new Set();
  for (const file of [...files].sort((a, b) => a.source_id - b.source_id)) {
    if (!Number.isSafeInteger(file.source_id) || seen.has(file.source_id)) fail('duplicate or invalid source ID');
    seen.add(file.source_id);
    const visit = (d, value, pointer, parent_key, ordinal, member_key) => {
      const row_key = JSON.stringify([file.source_id, file.document.id, parent_key, d.table, value?.id ?? member_key ?? pointer]);
      const personId = d.table === 'text_atlas_humans' ? value.id : d.table === 'text_atlas_additional_people' ? member_key : null;
      const stateId = d.table === 'text_atlas_states' ? value.id : value?.state_id ?? value?.national_state_id
        ?? (['states', 'exclusive_state_ids', 'authority_state_ids'].includes(d.path.at(-2)) ? value : null);
      const row = { source_id: file.source_id, json_pointer: pointer, row_key, parent_key, ordinal, member_key,
        person_ref: persons.has(personId) ? personId : null, state_ref: states.has(stateId) ? stateId : null };
      for (const n of d.nodes) {
        const v = get(value, n.path);
        const type = n.types.includes('map') && kind(v) === 'object' ? 'map' : kind(v);
        if (type !== null && !n.types.includes(type)) fail(pointer + '/' + n.path.join('/'));
        row[n.name + '__type'] = type;
        if (n.types.some((t) => !['object', 'array', 'map', 'null'].includes(t))) row[n.name] = type === 'boolean' ? Number(v) : ['object', 'array', 'map'].includes(type) ? null : v ?? null;
        if (type === 'object') {
          const allowed = d.nodes.filter((x) => x.path.length === n.path.length + 1 && n.path.every((p, i) => p === x.path[i])).map((x) => x.path.at(-1));
          if (Object.keys(v).some((key) => !allowed.includes(key))) fail('unknown field at ' + pointer);
        }
      }
      tables[d.table].push(Object.freeze(row));
      for (const child of children(d)) {
        const collection = get(value, child.relative);
        const childPointer = pointer + child.relative.map((part) => '/' + escape(part)).join('');
        if (child.mode === 'array' && Array.isArray(collection)) collection.forEach((v, i) => visit(child, v, childPointer + '/' + i, row_key, i, null));
        if (child.mode === 'map' && collection) Object.entries(collection).forEach(([k, v], i) => visit(child, v, childPointer + '/' + escape(k), row_key, i, k));
      }
    };
    for (const d of definitions.filter((d) => !d.parent)) {
      const value = file.document?.data?.[d.path[0]];
      if (value !== undefined) visit(d, value, '/data/' + d.path[0], null, 0, null);
    }
  }
  return Object.freeze(Object.fromEntries(Object.entries(tables).map(([k, rows]) => [k, Object.freeze(rows)])));
}

export function reconstructAtlasData({ tables, source_id }) {
  const restore = (d, row) => {
    let value;
    for (const n of d.nodes) {
      const type = row[n.name + '__type'];
      if (type === null) continue;
      const v = type === 'object' || type === 'map' ? {} : type === 'array' ? [] : type === 'null' ? null : type === 'boolean' ? Boolean(row[n.name]) : row[n.name];
      if (!n.path.length) value = v;
      else {
        const parent = get(value, n.path.slice(0, -1));
        if (parent && typeof parent === 'object') parent[n.path.at(-1)] = v;
      }
    }
    for (const child of definitions.filter((x) => x.parent === d.table)) {
      const collection = get(value, child.relative);
      for (const r of (tables[child.table] ?? []).filter((r) => r.source_id === source_id && r.parent_key === row.row_key).sort((a, b) => a.ordinal - b.ordinal)) collection[child.mode === 'map' ? r.member_key : r.ordinal] = restore(child, r);
    }
    return value;
  };
  const data = {};
  for (const d of definitions.filter((d) => !d.parent)) {
    const row = (tables[d.table] ?? []).find((r) => r.source_id === source_id);
    if (row) data[d.path[0]] = restore(d, row);
  }
  return data;
}
